head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.vScrenID = "ULDBNS20600.xml";
scwin.vRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_Search
 * 설명       : 발행기관을 조회한다.
 ***********************************************/
scwin.fn_Search = function() {
    if ($c.stf.compareFromToDate2(edt_Sdd, edt_Edd) == false) return;
    var param = '';
    param += "&{P}V_SDD=" + $c.stf.getObjectValue(edt_Sdd);
    param += "&{P}V_EDD=" + $c.stf.getObjectValue(edt_Edd);
    param += "&{P}V_BIZ_TP_CD=" + $c.stf.getObjectValue(cmb_BizTpCd);
    param += "&{P}V_ISUR_NM=" + $c.stf.getObjectValue(txb_IsurNm);
    param += "&{P}V_MKTACT_TP_CD=" + $c.stf.getObjectValue(cmb_MktactTpCd);
    var dsNm = 'BNS_APPL_LSTM_STAT';
    var qryId = 'lds.stf.bnslistbzappl.select.listApplLstmStat';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};


/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_NM: $c.stf.getObjectValue(txb_IsurNm)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_IsurNm, arrPar[0].ISUR_NM);
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_List.getCellData(dts_List.getRowPosition(), "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_List.getCellData(dts_List.getRowPosition(), "BND_LIST_PROCS_TP_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터 정의 (채권시장조치구분코드)
 ***********************************************/
scwin.fn_SetComboCode = function() {
    var arrCid = [];
    arrCid.push({
        cid: '03057',
        cnm: 'cmb_MktactTpCd'
    });
    $c.bns.fn_SetBnsComboToCode2(scwin.vScrenID, dts_Temp, arrCid, 'ALL');
};
scwin.gform_onload = function() {
    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Search);
    //처리기간설정
    $c.stf.fn_setFromToDate(1, edt_Sdd, edt_Edd);
    //setObjectValue(edt_Edd, cGetToday("yyyymmdd"));
    //채권시장조치구분코드
    scwin.fn_SetComboCode();
    //목록조회
    scwin.fn_Search();
};
scwin.img_Sdate_onclick = function() {
    popUpCalendar2(edt_Sdd);
};
scwin.img_Edate_onclick = function() {
    popUpCalendar2(edt_Edd);
};
scwin.bnt_Select_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    var fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_신청서류현황조회.xls";
    $c.data.downloadGridViewExcel(grd_List, "신청서류현황조회", "", '8');
};
scwin.img_IsurNm_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(img_IsurNm);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    txb_TotalCnt.setValue("총 " + rowcount + "건");
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.grd_List_OnClick = function(row, colid) {
    if (row > 0) // 해더 선택시 팝업창 뜨는것 수정 JACKAL_191129

    {
        var showPop = false;
        if (colid == 'SECU_STAT_CNT' && dts_List.getCellData(row, 'SECU_STAT_CNT') > 0) {
            showPop = true;
        } else if (colid == 'PAY_CERT_CNT' && dts_List.getCellData(row, 'PAY_CERT_CNT') > 0) {
            showPop = true;
        } else if (colid == 'ETC_CNT' && dts_List.getCellData(row, 'ETC_CNT') > 0) {
            showPop = true;
        }
        //  발행등록사실확인서 구분 추가 JACKAL_191129
        else if (colid == 'ISUREG_FACT_CONFRM_CNT' && dts_List.getCellData(row, 'ISUREG_FACT_CONFRM_CNT') > 0) {
            showPop = true;
        }
        if (showPop) {
            scwin.fn_GetPar = fn_GetCommonKey;
            $c.bns.fn_PopAttachDocSearch(grd_List);
        }
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.txb_IsurNm_onkeypress = function() {
    if ($c.stf.compareFromToDate2(edt_Sdd, edt_Edd)) {
        if (window.event.keyCode == 13) scwin.fn_Search();
    }
};
